import React, { useState, useEffect } from 'react';
import { CreditCard, Download, Clock, CheckCircle } from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';

const Payments = () => {
  const [bills, setBills] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');

  useEffect(() => {
    fetchBills();
  }, [filter]);

  const fetchBills = async () => {
    try {
      const params = filter !== 'all' ? { status: filter } : {};
      const response = await axios.get('/tenant/bills', { params });
      setBills(response.data);
    } catch (error) {
      toast.error('Failed to fetch bills');
    } finally {
      setLoading(false);
    }
  };

  const handlePayment = async (billId) => {
    try {
      // Create payment order
      const orderResponse = await axios.post('/payment/create-order', { billId });
      const { orderId, amount, currency, keyId } = orderResponse.data;

      // Initialize Razorpay
      const options = {
        key: keyId,
        amount: amount,
        currency: currency,
        name: 'Nestify Hostel',
        description: 'Rent Payment',
        order_id: orderId,
        handler: async (response) => {
          try {
            // Verify payment
            await axios.post('/payment/verify', {
              razorpayOrderId: response.razorpay_order_id,
              razorpayPaymentId: response.razorpay_payment_id,
              razorpaySignature: response.razorpay_signature,
              billId: billId
            });

            toast.success('Payment successful!');
            fetchBills();
          } catch (error) {
            toast.error('Payment verification failed');
          }
        },
        prefill: {
          name: 'Tenant Name',
          email: 'tenant@example.com'
        },
        theme: {
          color: '#2563eb'
        }
      };

      const rzp = new window.Razorpay(options);
      rzp.open();
    } catch (error) {
      toast.error('Failed to initiate payment');
    }
  };

  const downloadInvoice = async (billId) => {
    try {
      const response = await axios.get(`/payment/invoice/${billId}`, {
        responseType: 'blob'
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `invoice-${billId}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error) {
      toast.error('Failed to download invoice');
    }
  };

  if (loading) {
    return <div className="flex items-center justify-center h-64">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
    </div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-gray-900">Payments & Bills</h2>
        <div className="flex space-x-2">
          <button
            onClick={() => setFilter('all')}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${
              filter === 'all' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'
            }`}
          >
            All
          </button>
          <button
            onClick={() => setFilter('pending')}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${
              filter === 'pending' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'
            }`}
          >
            Pending
          </button>
          <button
            onClick={() => setFilter('paid')}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${
              filter === 'paid' ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'
            }`}
          >
            Paid
          </button>
        </div>
      </div>

      <div className="space-y-4">
        {bills.length > 0 ? (
          bills.map((bill) => (
            <div key={bill.id} className="bg-white rounded-lg shadow-sm border p-6">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">{bill.bill_number}</h3>
                  <p className="text-sm text-gray-500">
                    {bill.billing_month}/{bill.billing_year} • Room {bill.rooms?.room_number}
                  </p>
                </div>
                <div className="flex items-center space-x-2">
                  <span className={`badge ${
                    bill.status === 'paid' ? 'badge-success' : 'badge-warning'
                  }`}>
                    {bill.status === 'paid' ? (
                      <>
                        <CheckCircle className="h-3 w-3 mr-1" />
                        Paid
                      </>
                    ) : (
                      <>
                        <Clock className="h-3 w-3 mr-1" />
                        Pending
                      </>
                    )}
                  </span>
                </div>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
                <div>
                  <p className="text-sm text-gray-600">Room Rent</p>
                  <p className="font-medium">₹{bill.room_rent}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Electricity</p>
                  <p className="font-medium">₹{bill.electricity_charges}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Water</p>
                  <p className="font-medium">₹{bill.water_charges}</p>
                </div>
                <div>
                  <p className="text-sm text-gray-600">Total Amount</p>
                  <p className="font-bold text-lg">₹{bill.total_amount}</p>
                </div>
              </div>

              <div className="flex justify-end space-x-3">
                {bill.status === 'pending' ? (
                  <button
                    onClick={() => handlePayment(bill.id)}
                    className="btn-primary flex items-center"
                  >
                    <CreditCard className="h-4 w-4 mr-2" />
                    Pay Now
                  </button>
                ) : (
                  <button
                    onClick={() => downloadInvoice(bill.id)}
                    className="btn-secondary flex items-center"
                  >
                    <Download className="h-4 w-4 mr-2" />
                    Download Invoice
                  </button>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="text-center py-12">
            <CreditCard className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-500">No bills found</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Payments;
